@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + Description : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : string[]
}

class PickupRoute {
  + Date : date
}

class Item {
  + Dimensions : string
  + Weight : float
  + IsNonPerishableFood : boolean
}

class DistributionCenter {
}

class FoodBank {
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class Category {
  + Name : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class H2SEmployee {
}

class Delivery {
}

City "1" *-- "1..*" H2SLocation
H2SLocation "1" *-- "1" DistributionCenter
H2SLocation "1" *-- "1" FoodBank

Resident "1" -- "*" PickupRequest
PickupRequest "*" -- "1" Item
PickupRequest "*" -- "1" Resident

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" PickupRequest

Item "1" -- "0..1" Article
Item "1" -- "0..1" FoodBank : droppedOffAt

Article "*" -- "1" Category
H2SEmployee "1" -- "*" Article : examinesAndTags
H2SEmployee "1" -- "*" Delivery : arranges

Client "1" -- "*" Delivery
Delivery "*" -- "1" Article
Delivery "*" -- "1" VolunteerDriver

@enduml

